// Extras: the credits roll and achievements.
// Scrolling end credits. The "crew" is a joke; the real credits at the bottom must stay accurate (see RIGHTS.md).
(function () {
  const STUDIO = 'data:image/webp;base64,';
  // The crew, as an obituary page. Dark humor allowed (DB, 2026-11-10). The real credits below must stay accurate.
  const CREW = [
    ['Shelter Overseer', 'Guy Who Only Plays WoW', 'Day 212. Logged off for good during a raid. Not that kind.'],
    ['Lead Designer', 'Man Who Had Been Prepping Since Y2K', 'Day 3. Opened the canned peaches from 1999. He was right about everything except the peaches.'],
    ['Lead Programmer', 'Gooner Steve', 'Day 41. Went topside to find a charger. The charger was found.'],
    ['Assistant to Gooner Steve', 'Gooner Steve\u2019s Mom', 'Day 41, a little later. Went looking for Steve. Took the Bagel Bites. Nobody blames her.'],
    ['Narrative Lead', 'Q.U.E.S.T.', 'Still counting. Sends her condolences to everyone on this page.'],
    ['Lore Consultant', 'Guy at the Bar Who Said the Asteroid Was a Hoax', 'Day 365. Was looking up when it arrived. Briefly vindicated about nothing.'],
    ['Quality Assurance', 'Seth', 'Did not show up. Has not been seen. Presumed eaten, possibly by us.'],
    ['Water Engineer', 'Man Who Drank Straight From the Rain Filter', 'Day 19. Turned on Day 23. Still fixes the pipes. Please do not thank him.'],
    ['Head Chef', 'Gas Station Sushi Guy', 'Day 88. Served the stew. Became the stew.'],
    ['Dog Wrangler', 'Biscuit, a Very Good Boy', 'Day 140. Went missing during the hungry week. Everybody knows. Nobody says.'],
    ['Combat Choreographer', 'Florida Man', 'Day 7. Brought a bat to a Goliath. Brought it very confidently.'],
    ['Arms Consultant', 'Uncle Who Said "Back in My Day We Had Real Guns"', 'Day 55. Had real guns. Had no real rounds.'],
    ['Medical Advisor', 'WebMD', 'Diagnosed everyone with DMD. Was right 31 times out of 32.'],
    ['Antibiotics Supply', 'Guy Who Kept Half His Prescription "Just in Case"', 'Day 96. The case came. He had taken the other half for a cold in 2019.'],
    ['Morale Officer', 'Guy Who Reply-Alled the Emergency Broadcast', 'Day 12. Voted out of the shelter by everyone, on the same thread.'],
    ['Leadership Coach', 'Middle Manager Who Survived Three Coups', 'Day 201. Did not survive the fourth. Left a very detailed handover.'],
    ['Childcare', 'An iPad With 4% Battery', 'Day 2. Died first. The children have never forgiven any of us.'],
    ['Relationship Counselor', 'The Couple in Bunk 6', 'Day 160. Said "till death do us part" and meant it far too literally.'],
    ['Quarantine Officer', 'Guy Who Said "It\u2019s Just a Scratch"', 'Day 34. It was 32 scratches.'],
    ['Real Estate', 'Hollow Creek', 'Still standing. Will not return your calls. Has your dog.'],
    ['Interdimensional Liaison', 'The Thing That Came Through the Seam', 'Not dead. Not alive. On a payroll nobody remembers approving.'],
    ['Financial Officer', 'Crypto Uncle', 'Day 77. Traded the last bottle of antibiotics for a coin called $BUNKER. Down 100%.'],
    ['Marketing', 'Twitch Streamer With 3 Viewers', 'Day 130. Went live from the surface for the views. Got 4.'],
    ['Weather Department', 'The Black Rain', 'Never died. Never stopped. Sends its regards to the roof.'],
    ['Playtester', 'Your Bad Friend Buddy', 'Day 365. Ate the dog, blamed the leader, made it to the end. Rated the apocalypse one star.'],
    ['Uncredited', 'Everyone Else', 'Day 1 through Day 365. Their names are on the Wall. Somebody scratched them in by candlelight.'],
  ];
  const TRACKS = 'The Haunting, Deeper, Halls of Despair, Purgatory\u2019s Mansion, Retribution, Faith, Ominosity, Dark Knight, Reign of Anarchy, Assault on Mist Castle, Nevermore';

  function play(stage, done) {
    const SA = globalThis.ShelterAudio, prevScene = SA && SA.scene;
    if (SA) SA.setScene('credits');
    const el = document.createElement('div');
    el.className = 'creditsRoll';
    el.innerHTML = `<div class="roll">
      <h1>TOFU</h1><div class="sub">Earth Apocalypse Survival Shelter</div>
      <div class="sec">IN MEMORIAM</div><div class="obit-lead">The people who made this game, and how the end found them.</div>
      ${CREW.map(([r, n, d]) => `<div class="role">${r}</div><div class="who">${n}</div><div class="obit">${d}</div>`).join('')}
      <div class="sec">FOR REAL THIS TIME</div>
      <div class="role">A game by</div><div class="who"><img class="studioLogo" src="${STUDIO}" alt="Drunken Norns"><br>Drunken Norns</div>
      <div class="role">Created by</div><div class="who">Buddy</div>
      <div class="role">Based on</div><div class="who">TOFU: Threads of Fate Universe, the tabletop RPG by Buddy</div>
      <div class="role">Design, code and writing made with</div><div class="who">Claude</div>
      <div class="role">Art</div><div class="who">Generated locally with FLUX.2 Klein (Apache 2.0) and directed by Buddy</div>
      <div class="role">Music</div><div class="who">Tanner Helland (tannerhelland.com/music, CC BY 4.0)<br><small>${TRACKS}</small></div>
      <div class="role">Town maps</div><div class="who">Real streets and shops &copy; OpenStreetMap contributors, via Overture Maps (ODbL)</div>
      <div class="role">Sound effects</div><div class="who">Kenney (kenney.nl, CC0), plus wind, drones and things in the dark made in code</div>
      <div class="note">No dogs were harmed in the making of this game.<br>Several went missing. Everyone knows why.</div>
      <div class="last">Thanks for surviving.<br><small>Most of them didn\u2019t. Light a candle. Then try again.</small></div>
    </div><button class="skip" type="button">Skip &#9656;&#9656;</button>`;
    stage.appendChild(el);
    const roll = el.querySelector('.roll'), H = el.clientHeight || 720;
    const secs = Math.max(45, roll.scrollHeight / 55);
    const a = roll.animate([{ transform: `translateY(${H * .55}px)` }, { transform: `translateY(${-roll.scrollHeight}px)` }], { duration: secs * 1000, easing: 'linear', fill: 'forwards' });
    let over = false;
    const finish = () => { if (over) return; over = true; a.cancel(); window.removeEventListener('keydown', onKey, true); el.remove(); if (SA && prevScene) SA.setScene(prevScene); done && done(); };
    const onKey = e => { if (e.key === 'Escape' || e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); finish(); } };
    window.addEventListener('keydown', onKey, true);
    a.onfinish = finish;
    el.querySelector('.skip').onclick = finish;
    // hold to fast-forward
    el.addEventListener('pointerdown', e => { if (e.target.closest('.skip')) return; a.playbackRate = 5; });
    el.addEventListener('pointerup', () => { a.playbackRate = 1; });
  }
  globalThis.ShelterCredits = { play };
})();

// Achievements. Saved in the browser, and sent to Steam when the desktop build provides window.tofuSteam.
// API names must match steam/achievements.csv. Invented for DB's review.
(function () {
  const E = globalThis.ShelterEngine, KEY = 'tofu.shelter.ach';
  const ends = () => { try { return Object.keys(JSON.parse(localStorage.getItem('tofu.shelter.endings') || '{}')).length; } catch (e) { return 0; } };
  const dogs = S => (E.dogs ? E.dogs(S) : []);
  const LIST = [
    { id: 'FIRST_NIGHT', n: 'Lights Out', d: 'Survive your first night underground.', t: S => S.day >= 2 },
    { id: 'FIRST_RAID', n: 'Hold the Gate', d: 'Win a fight at the Gate.', t: S => (S.stat.raids || 0) >= 1 && (S.stat.foes || 0) >= 1 },
    { id: 'FIRST_QUEST', n: 'Out There', d: 'Come home from a quest.', t: S => (S.stat.quests || 0) >= 1 },
    { id: 'FIRST_LOSS', n: 'A Name on the Wall', d: 'Lose someone. It will not be the last time.', t: S => S.memorial.some(m => !m.dog && !m.left) },
    { id: 'DAY_100', n: 'One Hundred Mornings', d: 'Reach Day 100.', t: S => S.day >= 100 },
    { id: 'DAY_200', n: 'Old Hands', d: 'Reach Day 200.', t: S => S.day >= 200 },
    { id: 'ELEVENTH_HOUR', n: 'The 11th Hour', d: 'Be there when the sky falls.', t: S => S.day >= 365 },
    { id: 'HARD_365', n: 'Hard Times', d: 'Reach the 11th Hour on Hard.', t: S => S.day >= 365 && S.diff === 'hard' },
    { id: 'NIGHTMARE_365', n: 'Nothing Left to Fear', d: 'Reach the 11th Hour on Nightmare.', t: S => S.day >= 365 && S.diff === 'nightmare' },
    { id: 'FIRST_ENDING', n: 'An Ending', d: 'See any ending. None of them are kind.', t: () => ends() >= 1 },
    { id: 'ENDINGS_5', n: 'Many Worlds', d: 'See 5 different endings.', t: () => ends() >= 5 },
    { id: 'ENDINGS_ALL', n: 'Every Door', d: 'See all 14 endings.', t: () => ends() >= 14 },
    { id: 'TRUTH', n: 'The Rain Is Not From Here', d: 'Learn the truth about Q.U.E.S.T.', t: S => !!(S.truth && S.truth.known) },
    { id: 'LEADER', n: 'Somebody Has to Decide', d: 'Appoint a leader.', t: S => !!(E.leader && E.leader(S)) },
    { id: 'LAWS_3', n: 'Rule of Law', d: 'Have three laws in force at once.', t: S => (S.laws || []).length >= 3 },
    { id: 'FIRST_BABY', n: 'Born Underground', d: 'A child is born in the shelter.', t: S => (S.stat.born || 0) >= 1 },
    { id: 'GROWN', n: 'Never Saw the Sky', d: 'A child grows up and joins the shelter.', t: S => S.people.some(p => 'takesAfter' in p) },
    { id: 'GOOD_BOY', n: 'Good Boy', d: 'Take in a dog.', t: S => dogs(S).length >= 1 },
    { id: 'PACK', n: 'The Pack', d: 'Have five dogs at once.', t: S => dogs(S).filter(d => d.alive).length >= 5 },
    { id: 'THE_STEW', n: 'Don\u2019t Ask About the Stew', d: 'Do what you had to do to eat.', t: S => (S.stat.ate || 0) >= 1 || S.memorial.some(m => /The shelter ate/.test(m.why || '')) },
    { id: 'CROWDED', n: 'Standing Room Only', d: 'Shelter 40 adults at once.', t: S => E.humans(S).length >= 40 },
    { id: 'DEEP', n: 'Deeper Still', d: 'Build a room on the fourth level down or deeper.', t: S => S.rooms.some(r => r.row >= 3) },
    { id: 'DAMNED_KEPT', n: 'One of Us', d: 'Keep one of the Damned in the shelter.', t: S => E.living(S).some(p => p.damned && !p.away) },
    { id: 'DEMO_DONE', n: 'The Long Night', d: 'Survive the Long Night.', t: S => !!S.demoWon },
  ];
  const got = () => { try { return JSON.parse(localStorage.getItem(KEY) || '{}'); } catch (e) { return {}; } };
  const unlock = (a, quiet) => {
    const g = got(); if (g[a.id]) return false;
    g[a.id] = Date.now(); try { localStorage.setItem(KEY, JSON.stringify(g)); } catch (e) { }
    try { if (globalThis.tofuSteam) globalThis.tofuSteam.unlock(a.id); } catch (e) { }
    if (!quiet && globalThis.ShelterAchToast) globalThis.ShelterAchToast(a);
    return true;
  };
  const check = S => { if (!S || !S.stat) return; for (const a of LIST) { let ok = false; try { ok = a.t(S); } catch (e) { } if (ok) unlock(a); } };
  // send anything unlocked offline to Steam on start
  try { if (globalThis.tofuSteam) Object.keys(got()).forEach(id => globalThis.tofuSteam.unlock(id)); } catch (e) { }
  globalThis.ShelterAch = { LIST, check, got };
})();

/* Opening movie (2026-11-12): a motion comic before the first New Shelter, script approved by Buddy. Art is inlined as INTRO_ART in icons_gen.js.
   Lines are on-screen text for now; voice to come later (ElevenLabs, recorded by Buddy). '~' marks the girl, '...' a held silence.
   Each line stays up for a time set by its length, so the pacing follows the words. */
(() => {
  const OUT = 1, IN = 0; // outdoor shots get the black rain overlay
  const SHOTS = [
    ['sky', ['Eleven years ago, you all looked up and saw it coming.', 'You asked me how long you had. I told you the truth.'], { from: 'scale(1.18) translate(0,4%)', to: 'scale(1.04) translate(0,-2%)' }, OUT],
    ['tower', ['You never thanked me for it.'], { from: 'scale(1.05)', to: 'scale(1.2) translate(0,3%)' }, OUT, 'flash'],
    ['rain', ['Then the rain started. It was black, and it was warm.', 'It was death, and it never really stopped.'], { from: 'scale(1.15) translate(-3%,0)', to: 'scale(1.05) translate(2%,0)' }, OUT, 'flash'],
    ['turning', ['The ones it touched first got sick. Then they died, and then they got back up.', 'Part monster, part the person you remembered.', 'They still knew your name. That was the worst part.', 'The look of recognition in their eyes.'], { from: 'scale(1.02)', to: 'scale(1.32) translate(-4%,5%)' }, IN, 'eyes'],
    ['horde', ['Your cities went quiet in a week.', 'Your roads took a little longer.'], { from: 'scale(1.06)', to: 'scale(1.22)' }, OUT, 'flash', ['highway']], // Buddy: hold on the street of the turned, then the jammed highway
    ['ladder', ['Some of you made it to a hatch.', 'Not all of you made it inside.'], { from: 'scale(1.25) translate(0,-4%)', to: 'scale(1.05) translate(0,3%)' }, OUT],
    ['hatch', ['~Please open the door. I’m out here, and I’m so scared.', '~I know you’re in there. I can hear you. I’ll be really good, I promise.', '~My mom won’t wake up. Please, please, someone help me.', '...', '~Okay. That’s okay. I can wait.', '~You’ll run out of food before I do… and you’ll have to come out at some point.', 'You kept the door shut. Good.', 'She would have killed every one of you before morning.'], { from: 'scale(1.04)', to: 'scale(1.34)' }, IN, 'knock'],
    ['straws', ['Down here, there’s food for six days and room for forty.', 'When it runs short, someone will have to go without,', 'and someone will have to go find more.'], { from: 'scale(1.2) translate(3%,0)', to: 'scale(1.06) translate(-2%,0)' }, IN],
    ['wall', ['You will have to decide those things.', 'I can help you. It will get easier. I promise.'], { from: 'scale(1.04)', to: 'scale(1.2) translate(0,-3%)' }, IN],
    ['fall', ['You have a year until the darkness you saw in the sky arrives.', 'Until then, I’m here.', 'Counting for you, and counting on you.'], { from: 'scale(1.22)', to: 'scale(1.02)' }, OUT, 'flash'],
  ];
  const lineMs0 = l => l === '...' ? 2400 : Math.round(450 + l.split(/\s+/).length * 245);
  // Q.U.E.S.T.'s recorded narration (ElevenLabs, voice "Midnight"): INTRO_VO = { src, seg: [[start, end] per shot, seconds] } in icons_gen.js.
  // When it is there, her lines last as long as she takes to say them; the girl's lines still use reading time.
  const VO = () => globalThis.INTRO_VO && globalThis.INTRO_VO.seg ? globalThis.INTRO_VO : null;
  const isQ = l => l !== '...' && l[0] !== '~';
  // The girl (ElevenLabs "Candy", muffled; her last line pitched down) and the man's sobbing: INTRO_VO.hatch = { src, girl: [[start, end] x5], man: [start, end] }.
  // Her last line waits TURN ms for the lightning before she speaks.
  const H = () => { const v = VO(); return v && v.hatch && v.hatch.girl ? v.hatch : null; }, TURN = 1000;
  const girlIdx = (s, i) => s[1].slice(0, i + 1).filter(x => x[0] === '~').length - 1;
  const hatchMs = (s, i) => { const l = s[1][i], h = H(); if (!h) return 0;
    if (l === '...') return Math.round((h.man[1] - h.man[0]) * 1000) + 400;
    if (l[0] === '~') { const w = h.girl[girlIdx(s, i)]; return w ? Math.round((w[1] - w[0]) * 1000) + (l.startsWith('~You') ? TURN : 0) + 450 : 0; } return 0; };
  const lineMsIn = (s, i) => { const l = s[1][i], v = VO(), si = SHOTS.indexOf(s), hm = hatchMs(s, i); if (hm) return hm; if (!v || !isQ(l) || !v.seg[si]) return lineMs0(l);
    const q = s[1].filter(isQ), qi = q.indexOf(l), last = qi === q.length - 1, w = v.lines && v.lines[si] && v.lines[si][qi];
    if (w) return Math.round((w[1] - w[0]) * 1000) + (last ? 700 : 0); // measured from the pauses in her take
    const n = q.reduce((a, x) => a + x.length, 0), [a, b] = v.seg[si]; return Math.round((b - a) * 1000 * l.length / n) + (last ? 700 : 120); };
  const spokenMs = (s, i) => { const l = s[1][i], v = VO(), si = SHOTS.indexOf(s), h = H(); if (h && l[0] === '~') { const w = h.girl[girlIdx(s, i)]; return w ? (w[1] - w[0]) * 1000 : 0; } if (!v || !isQ(l) || !v.lines || !v.lines[si]) return 0; const w = v.lines[si][s[1].filter(isQ).indexOf(l)]; return w ? (w[1] - w[0]) * 1000 : 0; };
  const lineMs = l => lineMs0(l);
  const shotMs = s => s[1].reduce((a, l, i) => a + lineMsIn(s, i), 0) + 400;
  const KEY = 'tofu.shelter.intro';
  const seen = () => { try { return localStorage.getItem(KEY) === '1'; } catch (e) { return false; } };
  let grainUrl = '';
  const grain = () => {
    if (grainUrl) return grainUrl;
    try { const c = document.createElement('canvas'); c.width = c.height = 160; const g = c.getContext('2d'), d = g.createImageData(160, 160); for (let i = 0; i < d.data.length; i += 4) { const v = Math.random() * 255; d.data[i] = d.data[i + 1] = d.data[i + 2] = v; d.data[i + 3] = 26; } g.putImageData(d, 0, 0); grainUrl = c.toDataURL(); } catch (e) { }
    return grainUrl;
  };
  function play(stage, done) {
    const SA = globalThis.ShelterAudio, prevScene = SA && SA.scene, prevRain = SA ? SA.rain : 0, prevMusic = SA ? SA.music : false, ART = globalThis.INTRO_ART || {};
    try { localStorage.setItem(KEY, '1'); } catch (e) { }
    if (SA) { SA.setScene('dead'); SA.setRain(1); if (SA.en) SA.en.setAmbient(.2); } // the code-made drones and calls stay low under the movie
    const el = document.createElement('div');
    el.className = 'introFilm';
    el.innerHTML = `<div class="cam"><div class="shots"></div><div class="rainL"></div></div><div class="tint"></div><div class="flashL"></div><div class="grain" style="background-image:url(${grain()})"></div><div class="vig"></div><div class="bars"></div><div class="sub"><small class="who">Q.U.E.S.T.</small><div class="ln"></div></div><button class="skip" type="button">Skip &#9656;&#9656;</button>`;
    stage.appendChild(el);
    const $ = s => el.querySelector(s), shotsEl = $('.shots'), ln = $('.ln'), sub = $('.sub'), fl = $('.flashL'), who = $('.who'), cam = $('.cam'), rainL = $('.rainL'), tint = $('.tint');
    if (globalThis.ShelterBlackRain) globalThis.ShelterBlackRain(rainL);
    const timers = []; let over = false;
    const later = (ms, f) => timers.push(setTimeout(() => { if (!over) f(); }, ms));
    const say = (t, spoken = 0) => { // spoken: how long she takes to say it, so the words appear as she says them

      ln.style.opacity = 0;
      later(280, () => {
        if (t === '...') { ln.innerHTML = ''; who.textContent = ''; return; }
        const g = t[0] === '~', txt = g ? t.slice(1) : t;
        who.textContent = g ? 'THE GIRL OUTSIDE' : 'Q.U.E.S.T.'; ln.classList.toggle('girl', g);
        const ws = txt.split(' '), step = spoken ? Math.max(40, (spoken - 420) / ws.length) : (g ? 70 : 95);
        ln.innerHTML = ws.map((w, i) => `<span style="animation-delay:${Math.round(i * step)}ms">${w}</span>`).join(' ');
        ln.style.opacity = 1;
      });
    };
    const flash = at => later(at, () => { thunder(); // Buddy: thunder with the tower lightning and every shake
      fl.animate([{ opacity: 0 }, { opacity: .85 }, { opacity: .1 }, { opacity: .6 }, { opacity: 0 }], { duration: 650, easing: 'ease-out' });
      cam.animate([{ transform: 'translate(0,0)' }, { transform: 'translate(-6px,4px)' }, { transform: 'translate(5px,-3px)' }, { transform: 'translate(0,0)' }], { duration: 300 });
    });
    let cur = null;
    const ins = (k, fade = 900, pan = null) => { // pan: [from, to, ms] for a new angle that moves on its own // an insert shot over the current one; a new insert starts from the old one's zoom so a fade reads as a change in place
      const old = cur; cur = null;
      if (k) {
        const x = document.createElement('div'); x.className = 'shot'; x.style.backgroundImage = `url(${ART[k] || ''})`; shotsEl.appendChild(x);
        const from = old ? getComputedStyle(old).transform : 'scale(1.05)';
        if (pan) x.animate([{ transform: pan[0] }, { transform: pan[1] }], { duration: pan[2], easing: 'cubic-bezier(.3,0,.7,1)', fill: 'forwards' });
        else x.animate([{ transform: from === 'none' ? 'scale(1.05)' : from }, { transform: 'scale(1.3)' }], { duration: 9000, easing: 'linear', fill: 'forwards' });
        x.animate([{ opacity: 0 }, { opacity: 1 }], { duration: fade, fill: 'forwards' }); cur = x;
      }
      if (old) later(k ? fade : 0, () => { old.animate([{ opacity: 1 }, { opacity: 0 }], { duration: k ? 100 : 700, fill: 'forwards' }).onfinish = () => old.remove(); });
    };
    const v = VO(); let voEl = null, voStop = null;
    try { if (v && v.src) { voEl = new Audio(v.src); voEl.preload = 'auto'; } } catch (e) { voEl = null; }
    let duckT = null; // music sits low while anyone speaks and only comes back up after a real pause, so it never pumps between lines or pictures
    const duckOn = () => { clearTimeout(duckT); if (SA) SA.duck = .4; }, duckOff = () => { clearTimeout(duckT); duckT = setTimeout(() => { if (SA) SA.duck = 1; }, 2500); };
    const speak = si => { // play this shot's stretch of the narration
      if (!voEl || !v.seg[si] || (SA && SA.sound === false)) return; const [a, b] = v.seg[si];
      try { const o = globalThis.ShelterOpts; voEl.volume = Math.min(1, o && o.o && o.o.sfx != null ? o.o.sfx / 100 : 1); voEl.currentTime = a; const p = voEl.play(); if (p) p.catch(() => { }); } catch (e) { }
      clearTimeout(voStop); duckOn(); voStop = setTimeout(() => { try { voEl.pause(); } catch (e) { } duckOff(); }, (b - a) * 1000 + 150);
    };
    const h = H(); let hEl = null, hStop = null;
    try { if (h && h.src) { hEl = new Audio(h.src); hEl.preload = 'auto'; } } catch (e) { hEl = null; }
    const hatchSay = w => { // play one clip from the hatch track
      if (!hEl || !w || (SA && SA.sound === false)) return; const [a, b] = w;
      try { const o = globalThis.ShelterOpts; hEl.volume = Math.min(1, o && o.o && o.o.sfx != null ? o.o.sfx / 100 : 1); hEl.currentTime = a; const p = hEl.play(); if (p) p.catch(() => { }); } catch (e) { }
      clearTimeout(hStop); duckOn(); hStop = setTimeout(() => { try { hEl.pause(); } catch (e) { } duckOff(); }, (b - a) * 1000 + 100);
    };
    const thunder = () => { // a close thunder crack and long roll, made in code on the game's audio context
      try { const en = SA && SA.en, ctx = en && en.ctx; if (!ctx || SA.sound === false) return; const t0 = ctx.currentTime, len = 4.5, b = ctx.createBuffer(1, ctx.sampleRate * len, ctx.sampleRate), d = b.getChannelData(0);
        for (let i = 0, last = 0; i < d.length; i++) { const t = i / ctx.sampleRate, w = Math.random() * 2 - 1; last = last * .985 + w * .015; d[i] = (t < .12 ? w * (1 - t / .12) : 0) * .9 + last * 9 * Math.exp(-t * .9) * (1 + .5 * Math.sin(t * 7)); }
        const s = ctx.createBufferSource(), f = ctx.createBiquadFilter(), g = ctx.createGain(); s.buffer = b; f.type = 'lowpass'; f.frequency.value = 900; const o = globalThis.ShelterOpts; g.gain.value = 1.4 * (o && o.o && o.o.sfx != null ? o.o.sfx / 100 : 1);
        s.connect(f); f.connect(g); g.connect(ctx.destination); s.start(t0); } catch (e) { }
    };
    const quiet = on => { if (!SA) return; SA.setRain(on ? 0 : 1); SA.music = on ? false : prevMusic; };
    let t = 500;
    el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 900 });
    SHOTS.forEach(s => {
      const [k, lines, pan, out, fx] = s, ms = shotMs(s), start = t;
      later(start, () => {
        const d = document.createElement('div'); d.className = 'shot'; d.style.backgroundImage = `url(${ART[k] || ''})`;
        shotsEl.appendChild(d);
        d.animate([{ transform: pan.from }, { transform: pan.to }], { duration: ms + 1600, easing: 'cubic-bezier(.3,0,.7,1)', fill: 'forwards' });
        d.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 1100, fill: 'forwards' });
        later(ms + 900, () => { d.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 800, fill: 'forwards' }).onfinish = () => d.remove(); });
        rainL.style.opacity = out ? .75 : 0;
        sub.style.opacity = 1;
        let at = 350, voiced = false;
        lines.forEach((l, li) => {
          const turn = h && l.startsWith('~You') ? TURN : 0;
          { const sp = spokenMs(s, li); later(at + turn, () => say(l, sp)); }
          if (isQ(l) && !voiced) { voiced = true; later(at, () => speak(SHOTS.indexOf(s))); }
          if (h && l[0] === '~') { const w = h.girl[girlIdx(s, li)]; later(at + turn, () => hatchSay(w)); }
          if (h && l === '...') later(at + 200, () => hatchSay(h.man));
          if (l === '...') { later(at, () => quiet(true)); later(at + lineMsIn(s, li) - 200, () => quiet(false)); }
          if (fx === 'knock') {
            // cut outside to the girl while she begs, back to the hands for the silence, then her face turns on her last line
            // while she begs, the camera goes back and forth between her outside (several angles) and the man inside holding the hatch
            const G = ['girl_sad', 'girl_face', 'girl_fists', 'girl_wide'].filter(a => ART[a]), M = ['man_cry', 'man_hold', 'man_face'].filter(a => ART[a]), gi = girlIdx(s, li), dur = lineMsIn(s, li);
            if (l[0] === '~' && gi <= 2) { later(at, () => ins(G[gi % G.length], 300)); later(at + dur * .5, () => ins(M[gi % M.length], 300)); }
            if (l.startsWith('~Okay')) later(at, () => ins(G[0], 500));
            if (l === '...') later(at, () => ins('man_cry'));
            if (l.startsWith('~You')) later(at + (h ? 150 : 800), () => { // lightning: she is evil when the light comes back
              fl.animate([{ opacity: 0 }, { opacity: 1 }, { opacity: .15 }, { opacity: .9 }, { opacity: 0 }], { duration: 900, easing: 'ease-out' });
              cam.animate([{ transform: 'translate(0,0)' }, { transform: 'translate(-9px,6px)' }, { transform: 'translate(7px,-5px)' }, { transform: 'translate(0,0)' }], { duration: 350 });
              if (SA) thunder(); // one thunder crack as she turns (Buddy: no knocking or latch sounds)
              later(90, () => { ins('girl_evil', 60); tint.style.opacity = 1; });
            });
            if (l.startsWith('You kept')) later(at, () => { ins(null); tint.style.opacity = 0; });
          }
          at += lineMsIn(s, li);
        });
        if (fx === 'flash') { flash(ms * .3); if (ms > 5000) flash(ms * .74); }
        if (fx !== 'knock') { // more motion: cut to closer angles (INTRO_ART key_b, key_c) on her lines, each with its own push in or pull back
          const alts = (s[5] || [k + '_b', k + '_c']).filter(a => ART[a]), starts = []; let a2 = 350; lines.forEach((l, li) => { starts.push(a2); a2 += lineMsIn(s, li); });
          const cuts = s[5] ? starts.slice(1) : starts.length >= 3 ? starts.slice(1, 3) : [ms * .34, ms * .67], PANS = [['scale(1.12) translate(-2%,1%)', 'scale(1.28) translate(1%,-1%)'], ['scale(1.3) translate(2%,0)', 'scale(1.1) translate(-1%,1%)']];
          alts.forEach((a, i) => { if (cuts[i] != null) { const len = (i + 1 < alts.length && cuts[i + 1] != null ? cuts[i + 1] : ms) - cuts[i] + 1500; later(cuts[i], () => ins(a, 450, [PANS[i][0], PANS[i][1], len])); } });
          if (alts.length) later(ms + 500, () => ins(null));
        }
        if (fx === 'eyes') later(ms - 2600, () => d.animate([{ filter: 'contrast(1.08) saturate(.85) brightness(.82)' }, { filter: 'contrast(1.3) saturate(.5) brightness(.55)' }], { duration: 2400, fill: 'forwards' }));
      });
      t += ms;
    });
    later(t, () => { sub.style.opacity = 0; rainL.style.opacity = .5; shotsEl.innerHTML = `<div class="ttl"><h1>TOFU</h1><div>Earth Apocalypse Survival Shelter</div><p>1 year until the end of the world</p>${!globalThis.tofuDesktop || (globalThis.ShelterEngine && ShelterEngine.DEMO && ShelterEngine.DEMO.on) ? '<p class="wl">Only weeks until release. Wishlist now on Steam.</p>' : ''}</div>`; });
    later(t + 5000, () => finish());
    const finish = () => {
      if (over) return; over = true; timers.forEach(clearTimeout); clearTimeout(voStop); try { if (voEl) voEl.pause(); } catch (e) { } window.removeEventListener('keydown', onKey, true);
      el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 600 }).onfinish = () => el.remove();
      clearTimeout(duckT); if (SA) { SA.duck = 1; if (SA.applyVol) SA.applyVol(); SA.music = prevMusic; if (prevScene) SA.setScene(prevScene); SA.setRain(prevRain); }
      done && done();
    };
    const onKey = e => { if (e.key === 'Escape' || e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); finish(); } };
    window.addEventListener('keydown', onKey, true);
    $('.skip').onclick = finish;
  }
  globalThis.ShelterIntro = { play, seen, SHOTS, length: () => (SHOTS.reduce((a, s) => a + shotMs(s), 0) + 5500) / 1000 };
})();
